-- Generated fixture UUIDs only. The entire verification is rolled back.
begin;
create temp table game_invite_test_users(code text,id uuid,handle text);
insert into game_invite_test_users select code,gen_random_uuid(),'invite_'||code||'_'||substr(md5(random()::text),1,8) from (values('a'),('b'),('c'),('d')) x(code);
insert into auth.users(id,email,raw_user_meta_data) select id,handle||'@example.invalid',jsonb_build_object('display_name',code) from game_invite_test_users;
insert into public.profiles(id,handle,display_name) select id,handle,code from game_invite_test_users on conflict(id) do update set handle=excluded.handle,display_name=excluded.display_name;
update public.profiles set share_deck_stats=true where id in(select id from game_invite_test_users);
insert into public.friend_connections(requester_id,recipient_id,status,accepted_at) select a.id,b.id,'accepted',now() from game_invite_test_users a cross join game_invite_test_users b where a.code='a' and b.code in('b','c');
create temp table game_invite_test_decks(id uuid,owner_id uuid);
insert into game_invite_test_decks select gen_random_uuid(),id from game_invite_test_users;
insert into public.decks(id,owner_id,name,commander,decklist) select d.id,d.owner_id,u.code||' deck',u.code||' commander','' from game_invite_test_decks d join game_invite_test_users u on u.id=d.owner_id;
insert into public.personal_games(owner_id,deck_id,won) select owner_id,id,false from game_invite_test_decks;
do $$
declare a uuid;b uuid;c uuid;outsider uuid;ad uuid;bd uuid;cd uuid;source uuid;second_source uuid;bi uuid;ci uuid;bc uuid;cc uuid;payload jsonb;result jsonb;original jsonb;expected jsonb;
begin
 select id into a from game_invite_test_users where code='a';select id into b from game_invite_test_users where code='b';select id into c from game_invite_test_users where code='c';select id into outsider from game_invite_test_users where code='d';
 select id into ad from game_invite_test_decks where owner_id=a;select id into bd from game_invite_test_decks where owner_id=b;select id into cd from game_invite_test_decks where owner_id=c;
 payload:=jsonb_build_array(jsonb_build_object('name','You','commander','a commander','private_seat_note','do not share'),jsonb_build_object('name','B saved','commander','b commander','friend_id',b::text,'friend_deck_id',bd::text),jsonb_build_object('name','C saved','commander','c commander','friend_id',c::text,'friend_deck_id',cd::text));
 perform set_config('request.jwt.claim.sub',a::text,true);
 insert into public.personal_games(owner_id,deck_id,played_at,won,players,first_player,winner_player,notes) values(a,ad,'2026-01-01',false,payload,2,1,'PRIVATE SOURCE NOTES') returning id into source;
 if (select count(*) from public.game_invitations where source_game_id=source)<>2 then raise exception 'Expected one invitation per tagged friend';end if;
 select id,snapshot into bi,original from public.game_invitations where source_game_id=source and recipient_id=b;select id into ci from public.game_invitations where source_game_id=source and recipient_id=c;
 if original ? 'notes' or original->'players'->0 ? 'private_seat_note' or original::text like '%friend_id%' then raise exception 'Private notes or unrelated profile IDs shared';end if;
 if (select count(*) from public.friend_notifications where game_invitation_id in(bi,ci) and kind='game_tagged')<>2 then raise exception 'Tagged notifications missing';end if;
 perform set_config('request.jwt.claim.sub',outsider::text,true);
 if public.list_game_invitations()<>'[]'::jsonb then raise exception 'Other invitations leaked';end if;
 begin perform public.respond_game_invitation(bi,'accept',ad);raise exception 'Outsider accepted invitation';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',b::text,true);
 if jsonb_array_length(public.list_game_invitations())<>1 then raise exception 'Recipient list wrong';end if;
 begin perform public.respond_game_invitation(bi,'accept',ad);raise exception 'Foreign deck allowed';exception when insufficient_privilege then null;end;
 update public.decks set commander='Changed later' where id=bd;
 result:=public.respond_game_invitation(bi,'accept',bd);bc:=(result->>'game_id')::uuid;
 select to_jsonb(g) into expected from public.personal_games g where id=bc;
 if expected->>'owner_id'<>b::text or not (expected->>'won')::boolean or expected->>'winner_player'<>'0' or expected->>'first_player'<>'2' then raise exception 'Recipient perspective wrong';end if;
 if expected->'players'->0->>'name'<>'You' or expected->'players'->0->>'commander'<>'b commander' or expected->'players'->1->>'name'<>'a' or expected->>'notes'<>'' then raise exception 'Snapshot/own-seat/private-notes error';end if;
 if (public.respond_game_invitation(bi,'accept',bd)->>'game_id')::uuid<>bc or (select count(*) from public.personal_games where owner_id=b)<>2 then raise exception 'Acceptance not idempotent';end if;
 if (select count(*) from public.game_invitations where source_game_id=bc)<>0 then raise exception 'Copy sent invitation loop';end if;
 update public.personal_games set players=jsonb_set(players,'{1,commander}','"Edited source commander"'),winner_player=2,played_at='2026-02-02',notes='Edited private source note' where id=source;
 if (select to_jsonb(g) from public.personal_games g where id=bc)<>expected then raise exception 'Source edit changed accepted copy';end if;
 if (select snapshot from public.game_invitations where id=ci)<>original then raise exception 'Source edit changed pending snapshot';end if;
 update public.personal_games set notes='B PRIVATE',won=false,winner_player=1 where id=bc;
 if (select notes from public.personal_games where id=source)<>'Edited private source note' then raise exception 'Copy edit changed original';end if;
 delete from public.personal_games where id=source;
 if not exists(select 1 from public.personal_games where id=bc) then raise exception 'Source delete cascaded';end if;
 perform set_config('request.jwt.claim.sub',c::text,true);
 result:=public.respond_game_invitation(ci,'accept',cd);cc:=(result->>'game_id')::uuid;
 if (select played_at from public.personal_games where id=cc)<>'2026-01-01'::date or (select won from public.personal_games where id=cc) or (select first_player from public.personal_games where id=cc)<>0 or (select winner_player from public.personal_games where id=cc)<>2 then raise exception 'Deleted-source acceptance or remapping failed';end if;
 delete from public.personal_games where id=bc;
 if not exists(select 1 from public.personal_games where id=cc) then raise exception 'One copy deletion removed another';end if;
 perform set_config('request.jwt.claim.sub',b::text,true);perform public.respond_game_invitation(bi,'accept',bd);
 if (select count(*) from public.personal_games where owner_id=b)<>1 then raise exception 'Deleted copy was reimported';end if;
 perform set_config('request.jwt.claim.sub',a::text,true);
 insert into public.personal_games(owner_id,deck_id,won,players,first_player,winner_player) values(a,ad,false,jsonb_set(payload,'{2}',jsonb_build_object('name','C manual','commander','c commander')),0,1) returning id into second_source;
 select id into bi from public.game_invitations where source_game_id=second_source and recipient_id=b;
 perform set_config('request.jwt.claim.sub',b::text,true);perform public.respond_game_invitation(bi,'decline');
 if (select count(*) from public.personal_games where owner_id=b)<>1 then raise exception 'Decline created game';end if;
 if exists(select 1 from public.friend_notifications where game_invitation_id=bi and read_at is null) then raise exception 'Decline left unread notification';end if;
 perform set_config('request.jwt.claim.sub',a::text,true);update public.personal_games set players=payload where id=second_source;
 if (select count(*) from public.game_invitations where source_game_id=second_source)<>2 then raise exception 'Newly tagged friend or duplicate logic failed';end if;
 perform public.friend_action((select handle from game_invite_test_users where code='c'),'remove');
 if not exists(select 1 from public.personal_games where id=cc) then raise exception 'Unfriend deleted accepted copy';end if;
 perform set_config('request.jwt.claim.sub',c::text,true);if public.list_game_invitations()<>'[]'::jsonb then raise exception 'Unfriend did not cancel pending invites';end if;
 execute 'set local role authenticated';
 if exists(select 1 from public.game_invitations where recipient_id<>c) then raise exception 'RLS leaked invitation';end if;
 execute 'reset role';
 if has_table_privilege('authenticated','public.game_invitations','UPDATE') or has_function_privilege('anon','public.respond_game_invitation(uuid,text,uuid)','EXECUTE') then raise exception 'Unsafe mutation grants';end if;
 raise notice 'PASS invitations, notifications, privacy, recipient scope, perspective, idempotence, no loops, independent edits/deletes, decline and unfriend';
end $$;
rollback;
